{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#0f1216; --card:#0f1720; --muted:#9aa7b2; --accent:#c7a6ff; --glass:rgba(255,255,255,0.04);
      --max-w:1100px; font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue";
    }
    html,body{height:100%;margin:0;background:#0b0e12;color:#eaf0f6}
    body{line-height:1.45}
    .page{min-height:100vh;background-image:url("assets/img/pattern.svg");background-repeat:repeat;}
    .wrap{max-width:var(--max-w);margin:0 auto;padding:48px 20px}
    nav{display:flex;gap:18px;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#2b213d,#6b4b9c);display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff}
    .navlinks a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
    .navlinks a:hover{color:#fff;background:rgba(255,255,255,0.03)}
    header.hero{display:grid;grid-template-columns:1fr;gap:20px;padding:44px 0}
    .kicker{color:var(--accent);font-weight:600}
    h1{font-size:clamp(28px,4vw,44px);margin:6px 0 0}
    p.lead{color:var(--muted);max-width:70ch}
    .meta{display:flex;gap:12px;margin-top:18px}
    .cta{background:linear-gradient(90deg,#a27dff,#6fd3ff);color:#08101a;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:700}
    .secondary{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:10px 14px;border-radius:10px;color:var(--muted)}

    section.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:14px;margin:26px 0}
    .grid-3{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }

    footer{margin:40px 0 20px;color:var(--muted);font-size:14px}

    /* Modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(2,6,12,0.6);display:none;align-items:center;justify-content:center;z-index:120}
    .modal-backdrop.active{display:flex}
    .modal{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:20px;border-radius:12px;max-width:720px;width:94%;box-shadow:0 10px 40px rgba(2,6,12,0.6)}
    .modal h3{margin:0 0 8px}
    .modal .tabs{display:flex;gap:8px;margin-bottom:12px}
    .tabs button{padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)}
    .tabs button.active{background:linear-gradient(90deg,#5b3fb3,#6fd3ff);color:#071016;border:none}
    .modal .panel{min-height:110px}
    .modal .controls{display:flex;gap:10px;align-items:center;margin-top:12px}
    .btn-ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:8px 12px;border-radius:8px;color:var(--muted)}

    .disclaimer{background:#1a1f24;padding:12px;border-left:4px solid #ffb37b;border-radius:6px;color:var(--muted);font-size:14px}

    @media(min-width:900px){
      header.hero{grid-template-columns:1fr 380px}
    }
  </style>
</head>
<body class="page">
  <div class="wrap">
    <nav>
      <div class="brand">
        <div class="logo">SB</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">Sound gatherings · {{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <div class="navlinks">
        <a href="index.html">Home</a>
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Plan</a>
        <a href="about.html">About</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html" class="cta">Reserve</a>
        <a href="contact.html" class="secondary">Reach</a>
      </div>
    </nav>

    <header class="hero">
      <div>
        <div class="kicker">The craft of holding silence with intention</div>
        <h1>We curate shared sound spaces for steady attention and rest.</h1>
        <p class="lead">Our gatherings are built to be practical: simple cues, clear transitions, and sound designs that make stepping out of the busy day feel possible. We blend tuned bowls, breath coaching, and space for reflection.</p>
        <div class="meta">
          <a href="book.html" class="cta">Plan your first visit</a>
          <button id="tryButton" class="secondary">Try a short exercise</button>
        </div>
      </div>
      <aside class="card reveal" style="align-self:start">
        <strong>How we approach sound</strong>
        <p style="color:var(--muted)">We build simple structures: invitation, sustained tone, and a return. The intention is to support clearer breath, a quieter mind, and practical calm you can carry home.</p>
        <div style="margin-top:12px" class="grid-3">
          <div>
            <strong>Structured</strong>
            <div style="color:var(--muted);font-size:13px">Clear openings and closings to orient attention.</div>
          </div>
          <div>
            <strong>Accessible</strong>
            <div style="color:var(--muted);font-size:13px">Tools that work for first-timers and regulars alike.</div>
          </div>
          <div>
            <strong>Thoughtful</strong>
            <div style="color:var(--muted);font-size:13px">Small cues for how to move from practice back to life.</div>
          </div>
        </div>
      </aside>
    </header>

    <section class="card reveal">
      <h2>Our story</h2>
      <p style="color:var(--muted)">We started as a handful of people looking for practices that fit between therapy and life tasks. Over time we found a steady rhythm that blends curated tones, guided breath, and moments to write or set an intention—tools you can use beyond the room.</p>
    </section>

    <section class="card reveal">
      <h2>Community offerings</h2>
      <div class="grid-3">
        <div>
          <strong>Gatherings</strong>
          <div style="color:var(--muted)">Drop-in events that follow a clear arc. Bring a mat or borrow one on site.</div>
        </div>
        <div>
          <strong>Private Sessions</strong>
          <div style="color:var(--muted)">One-on-one work: deeper focus, tailored sound, and targeted breathing practices.</div>
        </div>
        <div>
          <strong>Takeaway tools</strong>
          <div style="color:var(--muted)">Small retail items—eye pillows, a signature tuning handout—to support practice at home.</div>
        </div>
      </div>
    </section>

    <section class="card reveal">
      <h2>What to expect</h2>
      <ul style="color:var(--muted)">
        <li>Sessions last 45–70 minutes with clear arrival and closing guidance.</li>
        <li>Gentle movement and seated options are supported.</li>
        <li>Phones on silent; quiet conversation before and after is welcome.</li>
      </ul>
      <div style="margin-top:12px" class="disclaimer">
        <strong>Contraindications & safety:</strong>
        <div style="margin-top:6px">If you are pregnant, have uncontrolled epilepsy, recent head injury, are highly sensitive to sound, or have any implantable medical device that could be affected by sustained vibration, please consult a physician before attending. If you are in active crisis or need urgent mental health care, this is not a replacement for clinical treatment.</div>
      </div>
    </section>

    <section class="card reveal">
      <h2>Connect</h2>
      <p style="color:var(--muted)">Questions about accessibility, group programs, or partnerships? Reach out.</p>
      <div style="display:flex;gap:12px;margin-top:12px">
        <a href="mailto:{{EMAIL}}" class="secondary">Email us</a>
        <a href="tel:{{PHONE}}" class="secondary">Call</a>
        <a href="book.html" class="cta">Reserve a spot</a>
      </div>
    </section>

    <footer>
      <div>&copy; <span id="year"></span> {{BUSINESS_NAME}} — small-group sound offerings in {{CITY}}, {{STATE}} • <a href="privacy.html" style="color:var(--muted)">Privacy</a></div>
    </footer>
  </div>

  <!-- Try-it modal -->
  <div id="modal" class="modal-backdrop" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h3 id="modalTitle">Try a short practice</h3>
        <button id="closeModal" aria-label="Close" class="btn-ghost">Close</button>
      </div>
      <div class="tabs" role="tablist">
        <button class="tab active" data-mode="breath" role="tab" aria-selected="true">Breath</button>
        <button class="tab" data-mode="journal" role="tab">Journal</button>
        <button class="tab" data-mode="intention" role="tab">Intend</button>
      </div>
      <div class="panel" id="panel">
        <!-- dynamic content -->
      </div>
      <div class="controls">
        <button id="start" class="cta">Begin</button>
        <button id="stop" class="btn-ghost">Stop</button>
        <div id="timer" style="margin-left:auto;color:var(--muted)">00:00</div>
      </div>
    </div>
  </div>

  <script>
    // basic reveal on scroll
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){ reveals.forEach(r=>r.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); });
      },{threshold:0.12});
      reveals.forEach(r=>obs.observe(r));
    })();

    // Try-it modal logic
    (function(){
      const modal = document.getElementById('modal');
      const panel = document.getElementById('panel');
      const tryBtn = document.getElementById('tryButton');
      const closeModal = document.getElementById('closeModal');
      const tabs = Array.from(document.querySelectorAll('.tab'));
      const start = document.getElementById('start');
      const stop = document.getElementById('stop');
      const timerEl = document.getElementById('timer');
      let mode = 'breath';
      let timer = null; let remaining = 0; let interval = null;

      function setPanel(m){
        mode = m;
        if(m==='breath'){
          panel.innerHTML = '<p style="color:var(--muted)">Find a comfortable seat. We will follow a simple 4-6-8 pattern: inhale 4, hold 6, exhale 8. Use the start button when ready.</p>';
        } else if(m==='journal'){
          panel.innerHTML = '<p style="color:var(--muted)">Take three minutes to answer: What feels needing attention? What is one next step? Write or reflect quietly.</p>';
        } else if(m==='intention'){
          panel.innerHTML = '<p style="color:var(--muted)">Set a short, clear intention for the next hour. Keep it actionable and kind. We will hold this for two minutes silently.</p>';
        }
      }

      tabs.forEach(t=>t.addEventListener('click',()=>{
        tabs.forEach(x=>x.classList.remove('active')); t.classList.add('active');
        const m = t.getAttribute('data-mode');
        t.setAttribute('aria-selected','true');
        setPanel(m);
      }));

      tryBtn.addEventListener('click', ()=>{
        modal.classList.add('active'); modal.setAttribute('aria-hidden','false');
        document.body.style.overflow='hidden';
        setPanel('breath');
      });
      closeModal.addEventListener('click', ()=>{
        modal.classList.remove('active'); modal.setAttribute('aria-hidden','true');
        document.body.style.overflow='auto'; stopAction();
      });

      function updateTimerDisplay(sec){
        const s = String(sec%60).padStart(2,'0');
        const m = String(Math.floor(sec/60)).padStart(2,'0');
        timerEl.textContent = m+':'+s;
      }

      function stopAction(){ if(interval) clearInterval(interval); interval=null; timer=null; remaining=0; updateTimerDisplay(0); }

      start.addEventListener('click', ()=>{
        if(mode==='breath'){
          remaining = 60; // 1 minute guided
        } else if(mode==='journal'){
          remaining = 180; // 3 minutes
        } else {
          remaining = 120; // 2 minutes
        }
        updateTimerDisplay(remaining);
        if(interval) clearInterval(interval);
        interval = setInterval(()=>{
          remaining--; updateTimerDisplay(remaining);
          if(remaining<=0){ clearInterval(interval); interval=null; }
        },1000);
      });

      stop.addEventListener('click', ()=>{ stopAction(); });

      // keyboard accessibility: close on escape
      document.addEventListener('keydown',(e)=>{ if(e.key==='Escape' && modal.classList.contains('active')){ closeModal.click(); } });

      // inject year
      document.getElementById('year').textContent = new Date().getFullYear();
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQs — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--muted:#9fb3c0;--accent:#bda5ff}
    body{margin:0;background:linear-gradient(180deg,#071018 0%, #08121a 100%);color:#e7f1f6;font-family:Inter,system-ui, -apple-system, 'Segoe UI', Roboto}
    .wrap{max-width:960px;margin:0 auto;padding:36px}
    header{display:flex;justify-content:space-between;align-items:center}
    a.cta{background:linear-gradient(90deg,#bda5ff,#6fd3ff);padding:10px 14px;border-radius:10px;color:#061018;text-decoration:none;font-weight:700}
    .accordion{margin-top:22px}
    .q{border-radius:10px;padding:14px;background:rgba(255,255,255,0.02);margin-bottom:10px}
    .q summary{cursor:pointer;list-style:none;font-weight:700}
    .q p{color:var(--muted);margin:10px 0 0}

    .disclaimer{background:#172428;padding:12px;border-left:4px solid #ffb37b;border-radius:6px;color:var(--muted);font-size:13px;margin-top:16px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .reveal{transition:none;opacity:1;transform:none} }

    .try{margin-top:18px}

    /* small footer */
    footer{margin-top:34px;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="color:var(--muted);font-size:13px">Questions & practical notes</div>
      </div>
      <div>
        <a href="book.html" class="cta">Reserve a seat</a>
      </div>
    </header>

    <section class="reveal" style="margin-top:18px">
      <h2>Common questions</h2>
      <div class="accordion">
        <details class="q">
          <summary>What should I bring?</summary>
          <p>Comfortable clothing, something to lie on (yoga mat), a light blanket, and an open curiosity. We have a small selection of borrowed mats and blankets if you need them.</p>
        </details>
        <details class="q">
          <summary>How loud are sessions?</summary>
          <p>We use tuned metal and crystal bowls and layered textures. Volume is moderated for the room and there are quiet seating options in the back. If you are sound-sensitive, get in touch before your visit.</p>
        </details>
        <details class="q">
          <summary>Is this therapy?</summary>
          <p>These gatherings are supportive practices but not a substitute for mental health care. If you are receiving clinical treatment or are in crisis, please contact a licensed provider.</p>
        </details>
        <details class="q">
          <summary>Are children allowed?</summary>
          <p>Our public sessions are intended for adults. Family-friendly or intergenerational offerings will be noted where appropriate.</p>
        </details>
      </div>
    </section>

    <section class="reveal">
      <h3>Safety & contraindications</h3>
      <div class="disclaimer">
        <strong>Please note:</strong>
        <div style="margin-top:6px;color:var(--muted)">If you have uncontrolled seizures, a history of traumatic brain injury, are in the later stages of pregnancy, use certain implantable medical devices, or are highly sensitive to vibration, consult a medical professional before attending. If you are currently in acute psychological crisis, these events are not a substitute for clinical care.</div>
      </div>
    </section>

    <section class="reveal try">
      <h3>Curious? Try a short practice</h3>
      <p style="color:var(--muted)">A quick option to see how guided breath and intention feel—no booking required.</p>
      <button id="tryNow" class="cta">Try it now</button>
    </section>

    <footer class="reveal">
      <div>Questions not covered here? Email <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}" style="color:var(--muted)">{{PHONE}}</a>.</div>
    </footer>
  </div>

  <!-- Modal reused from site (lightweight) -->
  <div id="modal" style="display:none;position:fixed;inset:0;align-items:center;justify-content:center;background:rgba(2,6,12,0.6);z-index:90">
    <div style="background:#071018;padding:18px;border-radius:10px;max-width:560px;width:94%;color:#eaf0f6">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong id="title">Short exercise</strong>
        <button id="close" style="background:transparent;border:none;color:var(--muted)">Close</button>
      </div>
      <div id="content" style="margin-top:12px;color:var(--muted)">A simple breath: inhale 4, hold 4, exhale 6. Repeat for one minute.</div>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button id="begin" class="cta">Begin</button>
        <button id="end" style="background:transparent;border:1px solid rgba(255,255,255,0.04);padding:8px;border-radius:8px;color:var(--muted)">Stop</button>
        <div id="timersmall" style="margin-left:auto;color:var(--muted)">00:00</div>
      </div>
    </div>
  </div>

  <script>
    // reveal observer
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(i=>i.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); });
      },{threshold:0.08});
      items.forEach(i=>io.observe(i));
    })();

    // small modal for FAQ try-it
    (function(){
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('tryNow');
      const close = document.getElementById('close');
      const begin = document.getElementById('begin');
      const end = document.getElementById('end');
      const timersmall = document.getElementById('timersmall');
      let inter = null, rem = 0;
      tryBtn.addEventListener('click',()=>{ modal.style.display='flex'; document.body.style.overflow='hidden'; });
      close.addEventListener('click',()=>{ modal.style.display='none'; document.body.style.overflow='auto'; stop(); });
      begin.addEventListener('click',()=>{ rem=60; timersmall.textContent='01:00'; if(inter) clearInterval(inter); inter=setInterval(()=>{ rem--; timersmall.textContent=('0'+Math.floor(rem/60)).slice(-2)+':'+('0'+rem%60).slice(-2); if(rem<=0) clearInterval(inter); },1000); });
      end.addEventListener('click',()=>{ stop(); });
      function stop(){ if(inter) clearInterval(inter); inter=null; rem=0; timersmall.textContent='00:00'; }
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061017;--muted:#9fb3c0;--accent:#9ad1ff}
    body{margin:0;background:var(--bg);color:#e9f5fb;font-family:Inter,system-ui, -apple-system, 'Segoe UI', Roboto}
    .wrap{max-width:980px;margin:0 auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center}
    .form{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;margin-top:18px}
    label{display:block;margin-top:12px;font-weight:700}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:inherit}
    .row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
    .addons{display:flex;gap:8px;margin-top:12px}
    .addon{padding:10px;border-radius:10px;background:rgba(255,255,255,0.02);cursor:pointer}
    .addon.selected{outline:2px solid rgba(157,124,255,0.5)}
    .price{font-weight:800}
    .cta{background:linear-gradient(90deg,#bda5ff,#6fd3ff);padding:10px 14px;border-radius:10px;color:#061018;text-decoration:none;font-weight:700;border:none}
    .secondary{background:transparent;border:1px solid rgba(255,255,255,0.04);padding:10px;border-radius:10px;color:var(--muted)}

    .calendar{margin-top:18px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    .slot{padding:8px;border-radius:8px;background:rgba(0,0,0,0.2);margin-bottom:8px}

    .disclaimer{background:#13222a;padding:12px;border-left:4px solid #ffb37b;border-radius:6px;color:var(--muted);font-size:13px;margin-top:12px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 480ms ease,transform 480ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .reveal{transition:none;opacity:1;transform:none} }
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <div style="font-weight:800">Reserve a spot</div>
        <div style="color:var(--muted);font-size:13px">Choose a public gathering or book private support</div>
      </div>
      <div>
        <a href="index.html" class="secondary">Back</a>
      </div>
    </header>

    <main class="form reveal">
      <form id="booking" autocomplete="off">
        <label for="type">Service type</label>
        <select id="type">
          <option value="gathering">Community Gathering — $18</option>
          <option value="intensive">Focused Session — $65</option>
          <option value="private">Private Session — $120</option>
        </select>

        <div class="row">
          <div>
            <label for="name">Full name</label>
            <input id="name" placeholder="Your name" required>
          </div>
          <div>
            <label for="email">Email</label>
            <input id="email" placeholder="you@example.com" required>
          </div>
        </div>

        <label for="date">Preferred date</label>
        <input id="date" type="date">

        <label for="notes">Notes (accessibility, sensitivities)</label>
        <textarea id="notes" rows="3" placeholder="Tell us about any needs or concerns"></textarea>

        <div style="margin-top:12px">
          <strong>Add-ons</strong>
          <div class="addons">
            <div class="addon" data-price="12">Eye pillow — $12</div>
            <div class="addon" data-price="8">Ear protect pads — $8</div>
            <div class="addon" data-price="4">Printed notes — $4</div>
          </div>
        </div>

        <div style="margin-top:12px;display:flex;align-items:center;gap:12px">
          <div>Estimated total:</div>
          <div class="price" id="total">$18</div>
        </div>

        <div style="display:flex;gap:8px;margin-top:12px">
          <button type="submit" class="cta">Complete booking</button>
          <button type="button" id="trial" class="secondary">Try a short practice</button>
        </div>

        <div class="disclaimer">
          <strong>Health note:</strong>
          <div style="margin-top:6px;color:var(--muted)">If you have conditions sensitive to sustained vibration, implants, seizure conditions, or are pregnant, please consult a medical professional before attending. Our sessions are supportive but not clinical care.</div>
        </div>
      </form>
    </main>

    <aside class="calendar reveal">
      <h4 style="margin:0 0 8px">Upcoming dates</h4>
      <div class="slot"><strong>Next gathering:</strong> Friday, 7:00pm — Open seating</div>
      <div class="slot">Sunday morning, 9:30am — Gentle focus</div>
      <div class="slot">Next open private availability: Wed 10:00am</div>
      <div style="color:var(--muted);font-size:13px;margin-top:8px">We update this list hourly—if you need a different time, request it in the form above.</div>
    </aside>

  </div>

  <!-- Reusable small modal: guided exercise -->
  <div id="modal" style="display:none;position:fixed;inset:0;align-items:center;justify-content:center;background:rgba(2,6,12,0.6);z-index:90">
    <div style="background:linear-gradient(180deg,#071018,#08121a);padding:18px;border-radius:10px;max-width:640px;width:94%;color:#eaf1f8">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong id="mTitle">Quick practice</strong>
        <button id="close" style="background:transparent;border:none;color:var(--muted)">Close</button>
      </div>
      <div id="mContent" style="margin-top:10px;color:var(--muted)">Choose breath, journaling, or intention from the controls (accessible via keyboard).</div>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button id="mBreath" class="cta">Breath</button>
        <button id="mJournal" class="secondary">Journal</button>
        <button id="mIntent" class="secondary">Intend</button>
        <div id="mTimer" style="margin-left:auto;color:var(--muted)">00:00</div>
      </div>
    </div>
  </div>

  <script>
    // reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){ items.forEach(i=>i.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); }); },{threshold:0.08});
      items.forEach(i=>obs.observe(i));
    })();

    // pricing logic
    (function(){
      const type = document.getElementById('type');
      const addons = Array.from(document.querySelectorAll('.addon'));
      const totalEl = document.getElementById('total');
      let base = 18;
      const map = { 'gathering':18, 'intensive':65, 'private':120 };
      function compute(){
        base = map[type.value] || 18; let add = 0; addons.forEach(a=>{ if(a.classList.contains('selected')) add += Number(a.getAttribute('data-price')||0); });
        totalEl.textContent = '$' + (base + add);
      }
      type.addEventListener('change',compute);
      addons.forEach(a=>a.addEventListener('click',()=>{ a.classList.toggle('selected'); compute(); }));
      compute();

      document.getElementById('booking').addEventListener('submit', (e)=>{
        e.preventDefault();
        // lightweight validation and fake submit
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        if(!name || !email){ alert('Please provide name and email.'); return; }
        alert('Thanks — your reservation request has been received. We will follow up by email.');
        e.target.reset(); compute();
      });
    })();

    // modal practice handlers
    (function(){
      const modal = document.getElementById('modal');
      const close = document.getElementById('close');
      const mb = document.getElementById('mBreath');
      const mj = document.getElementById('mJournal');
      const mi = document.getElementById('mIntent');
      const mContent = document.getElementById('mContent');
      const mTimer = document.getElementById('mTimer');
      let interval=null, rem=0;

      function open(){ modal.style.display='flex'; document.body.style.overflow='hidden'; }
      function closeModal(){ modal.style.display='none'; document.body.style.overflow='auto'; stop(); }
      function stop(){ if(interval) clearInterval(interval); interval=null; rem=0; mTimer.textContent='00:00'; }
      function startCount(sec){ stop(); rem=sec; mTimer.textContent = ('0'+Math.floor(rem/60)).slice(-2)+':'+('0'+rem%60).slice(-2); interval = setInterval(()=>{ rem--; mTimer.textContent = ('0'+Math.floor(rem/60)).slice(-2)+':'+('0'+rem%60).slice(-2); if(rem<=0) clearInterval(interval); },1000); }

      document.getElementById('trial').addEventListener('click', ()=>{ open(); mContent.textContent='Choose a practice.'; });
      close.addEventListener('click', closeModal);
      mb.addEventListener('click', ()=>{ mContent.textContent='Breath pattern: inhale 4, hold 4, exhale 6. Begin when you are settled.'; startCount(60); });
      mj.addEventListener('click', ()=>{ mContent.textContent='Journal prompt: Where do you want your attention for the next hour? Write for three minutes.'; startCount(180); });
      mi.addEventListener('click', ()=>{ mContent.textContent='State a short intention: one sentence. Keep it kind and actionable. Hold silently for two minutes.'; startCount(120); });
    })();
  </script>
</body>
</html>"} 
